use eframe::egui::{self,Color32,Stroke,Visuals};
pub const PANEL_BG:Color32=Color32::from_rgb(238,238,238); pub const BORDER:Color32=Color32::from_rgb(170,170,170); pub const CLASSIC_BLUE:Color32=Color32::from_rgb(51,103,173); pub const HOVER_BLUE:Color32=Color32::from_rgb(220,232,248); pub const UI_SIZE:f32=12.0; pub const EDITOR_SIZE:f32=12.0; pub const MENU_HEIGHT:f32=24.0; pub const TOOL_ICON:f32=20.0; pub const STATUS_HEIGHT:f32=22.0;
pub fn apply(ctx:&egui::Context){ctx.all_styles_mut(|s|{s.visuals=Visuals{window_fill:PANEL_BG,panel_fill:PANEL_BG,widgets:egui::style::Widgets{noninteractive:egui::style::WidgetVisuals{bg_fill:PANEL_BG,weak_bg_fill:PANEL_BG,bg_stroke:Stroke::new(1.0,BORDER),fg_stroke:Stroke::new(1.0,Color32::from_rgb(30,30,30)),corner_radius:egui::CornerRadius::ZERO,expansion:0.0},inactive:egui::style::WidgetVisuals{bg_fill:Color32::from_rgb(245,245,245),weak_bg_fill:Color32::from_rgb(245,245,245),bg_stroke:Stroke::new(1.0,BORDER),fg_stroke:Stroke::new(1.0,Color32::DARK_GRAY),corner_radius:egui::CornerRadius::ZERO,expansion:0.0},hovered:egui::style::WidgetVisuals{bg_fill:HOVER_BLUE,weak_bg_fill:HOVER_BLUE,bg_stroke:Stroke::new(1.0,CLASSIC_BLUE),fg_stroke:Stroke::new(1.0,Color32::BLACK),corner_radius:egui::CornerRadius::ZERO,expansion:0.0},active:egui::style::WidgetVisuals{bg_fill:Color32::from_rgb(190,215,245),weak_bg_fill:Color32::from_rgb(190,215,245),bg_stroke:Stroke::new(1.0,CLASSIC_BLUE),fg_stroke:Stroke::new(1.0,Color32::BLACK),corner_radius:egui::CornerRadius::ZERO,expansion:0.0},open:egui::style::WidgetVisuals{bg_fill:HOVER_BLUE,weak_bg_fill:HOVER_BLUE,bg_stroke:Stroke::new(1.0,CLASSIC_BLUE),fg_stroke:Stroke::new(1.0,Color32::BLACK),corner_radius:egui::CornerRadius::ZERO,expansion:0.0}},..Visuals::light()}; s.spacing.item_spacing=egui::vec2(4.0,2.0);});}
#[cfg(test)]mod tests{#[test]fn seed_tokens_are_stable(){assert_eq!(super::UI_SIZE,12.0);}}
